window.DIGEST.foryou.push(...[{"id": "2112574567214461290", "url": "https://x.com/MSFTCopilot/status/2112574567214461290", "text": "See what Copilot can do inside Word. Draft faster, write more clearly, and easily summarize long documents using relevant Microsoft 365 context. Meet the Word team for live demos and Q&A on October 22. \n\nTo register, follow the link below and click \"Register Now.\" Then search for “Microsoft Copilot in Word: Turn a blank page into a polished draft” and click \"Select Session.\" \n\nhttps://aka.ms/WordLivewebinar?ocid=usoc_TWITTER_M365_spl100011514643214", "name": "Microsoft Copilot", "handle": "MSFTCopilot", "avatar": "https://pbs.twimg.com/profile_images/2102444721419485184/NCrN1V_3_200x200.jpg", "likes": 58, "rts": 6, "replies": 2, "views": 4667, "ts": 1792512001, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFAvxCXEAAoQYn.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.33, "thread": [], "tier": "worth"}, {"id": "2112618808859144267", "url": "https://x.com/ftcarpe/status/2112618808859144267", "text": "every slow model call in an agent stacks up. most of that wait isn't compute, it's memory\n\n@general_compute is adding @positron_ai 's chips to fix exactly that:\n\n✓ gpus read the prompt\n✓ positron's memory-first chips write the answer\n✓ one endpoint, one contract\n\natlas today, titan next, live q1 2027\n\nmy agent's loading spinner felt that", "name": "carpe", "handle": "ftcarpe", "avatar": "https://pbs.twimg.com/profile_images/2100922371536502784/mtPoXt0r_200x200.jpg", "likes": 61, "rts": 3, "replies": 0, "views": 8108, "ts": 1792522549, "media": [], "quote": {"id": "2112585266854604957", "url": "https://x.com/general_compute/status/2112585266854604957", "text": "Our heterogeneous cloud just got better. We're announcing a cluster scale deployment of @positron_ai as our next partner.\n\nWe believe demand for fast inference will outstrip supply for the next decade. Our bet on Positron is another step towards getting fast inference for opensource models into builders' hands.\n\nHardware goes live Q1 2027.\n\nThanks to @mitesh711, @trsohmers and the whole Positron team! We're excited for this partnership.\n\nLFG!", "name": "General Compute", "handle": "general_compute", "avatar": "https://pbs.twimg.com/profile_images/2063265967774584832/y1U0qHB3_200x200.jpg", "likes": 830, "rts": 58, "replies": 108, "views": 234978, "ts": 1792514552, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/640x360/KX7QPT-I86P0SW2r.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/1280x720/XBFGYfCEY_EsyfiI.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112585087921377280/pu/img/EYiImymSTr1OyRJQ.jpg", "dur": 47}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.33, "thread": [], "tier": "worth"}, {"id": "2112671240964219290", "url": "https://x.com/MrTacticalX/status/2112671240964219290", "text": "Claude Opus 5.5 vs Sonnet 5.5 (both on High)\n\nSame prompt. Same timeline. A cute animated Claude travels through 5 worlds, all code, zero assets.\n\n- Opus: 36 min, ~$7.20\n- Sonnet: 26 min, ~$4.60\n\nWhich one did better?", "name": "Mr Tactical", "handle": "MrTacticalX", "avatar": "https://pbs.twimg.com/profile_images/2109983814856396800/te17eghr_200x200.jpg", "likes": 44, "rts": 1, "replies": 6, "views": 4058, "ts": 1792535050, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112670940442025984/vid/avc1/1280x720/RjklgTz-28o5Bned.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112670940442025984/vid/avc1/1920x1080/51jrZIbsQaB1BjSS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112670940442025984/img/2irEj1xQriBIeSaT.jpg", "dur": 24}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.33, "thread": [], "tier": "worth"}, {"id": "2112667011209941056", "url": "https://x.com/bernirov/status/2112667011209941056", "text": "ALGUNOS MODOS RÁPIDOS DE IA SE PAGAN APARTE. ESTE REPO LLEGA A 4× LA VELOCIDAD DE LA DECODIFICACIÓN NORMAL Y EL CÓDIGO ES PÚBLICO.\n\nun agente espera al modelo decenas de veces seguidas. cada segundo cuenta.\n\nse llama eagle-4.\n\n961.6 tokens por segundo en una sola petición.\n\n→ 4× más rápido que decodificación normal\n→ 1.28× vs dflash 2 y 1.40× vs dspark en una petición\n→ a 512 peticiones a la vez: 1.70× vs dflash 2 y 1.99× vs dspark\n\nnúmeros del paper de eagle-4, no mis medidas. qwen 3.8 27b, 4× nvidia b300, speed-bench (qualitative split), T=0. otros modelos y hardware pueden dar otros resultados.\n\nmíralo esta noche, enlace del repo abajo.", "name": "berni", "handle": "bernirov", "avatar": "https://pbs.twimg.com/profile_images/2103766337755688960/A-013F8P_200x200.jpg", "likes": 22, "rts": 6, "replies": 10, "views": 7953, "ts": 1792534041, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGzc4yaIAE7cR4.png?name=orig"}], "quote": {"id": "2112660683670323531", "url": "https://x.com/EagleCorp/status/2112660683670323531", "text": "EAGLE-4 is here.\n\nFrom EAGLE-1 to EAGLE-3, we’ve kept making inference faster. \n\nEAGLE-4 is our fastest yet.\n\n961.6 tokens/s on @Alibaba_Qwen’s Qwen3.8-27B with TokenSpeed (BF16, 4× @NVIDIA B300, TP4, one request, T=0).\n\nGithub: https://github.com/eagle-hq/EAGLE-4", "name": "Eagle", "handle": "EagleCorp", "avatar": "https://pbs.twimg.com/profile_images/2057212553915248640/zgJtC7pK_200x200.jpg", "likes": 4174, "rts": 519, "replies": 376, "views": 1080426, "ts": 1792532532, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1280x720/-10uYli5CGPejFwB.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112660579664187392/vid/avc1/1920x1080/6UlvgUxk_hy6qXRU.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112660579664187392/img/oFNlAedcp82x1A_3.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.33, "thread": [], "tier": "worth"}, {"id": "2112678932608635079", "url": "https://x.com/BIGMayrr/status/2112678932608635079", "text": "SpaceXAI's Grok Bot team put their own bot templates in the marketplace, and this is a f*c*ing goldmine\n\nInstead of spending hours building an agent from scratch, you can import a template, connect your tools, and customize it for your workflow.\n\nHere are 10 bots worth checking out:\n\n1. Dr Eggbot → Creates specialized Grok Bots based on the task you want to automate.\n\n2. Engineer Bot → Oversees cloud coding agents and monitors their pull requests while you stay in control of merging.\n\n3. Stalk Bot → Tracks competitors, spots product and pricing changes, and gives you sourced reports.\n\n4. Haggle Bot → Finds unnecessary SaaS expenses and prepares negotiation drafts to help lower your bills.\n\n5. Proto Bot → Turns feature ideas into working prototypes and submits draft PRs for review.\n\n6. Video Editor → Selects the best footage, creates vertical videos, and adds captions with an edit plan for approval.\n\n7. Figma Bro → Converts Figma designs into development specs and checks components against your design system.\n\n8. Distro Bot → Helps manage marketing campaigns and creative work while keeping spending and publishing under your control.\n\n9. Startup QA Bot → Tests your product, captures bugs with screenshots, and documents how to reproduce them.\n\n10. Signal Prospector → Finds potential buyers through CRM and product data, then drafts personalized outreach based on those signals.\n\nThe interesting part isn’t just having 10 different bots.\n\nIt’s being able to start with a workflow someone has already built and adapt it to your own needs.\n\nBefore writing another massive system prompt, check whether there’s already a bot for the job.\n\nSave this for later https://x.com/monokern/status/2111074067461611540/video/1", "name": "Mayor.", "handle": "BIGMayrr", "avatar": "https://pbs.twimg.com/profile_images/2085479405451689984/WXnZ_8Ii_200x200.jpg", "likes": 31, "rts": 3, "replies": 9, "views": 1200, "ts": 1792536883, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111073917674676225/vid/avc1/720x900/bc2QtYfCN5qjk5aR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111073917674676225/vid/avc1/1080x1350/nMWuRKudbCwhMW6K.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111073917674676225/img/U_MOgMPXXDJL3YcR.jpg", "dur": 32}], "quote": {"id": "2094299600404312496", "url": "https://x.com/BIGMayrr/status/2094299600404312496", "text": "https://x.com/i/article/2093549496206544897", "name": "Mayor.", "handle": "BIGMayrr", "avatar": "https://pbs.twimg.com/profile_images/2085479405451689984/WXnZ_8Ii_200x200.jpg", "likes": 173, "rts": 12, "replies": 11, "views": 132172, "ts": 1788154909, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.33, "thread": [], "tier": "worth"}, {"id": "2112575764994613735", "url": "https://x.com/OpenDesignHQ/status/2112575764994613735", "text": "Quick clarification: Go’s allowance has doubled for Motion Week 🎉 🎯\n\nBefore: $30/week (~$120/month)\nDuring the promo: up to $60/week — a 100% increase!\n\nDeepSeek’s off-peak pricing applies 24/7 throughout the promo. Sorry for mixing monthly and weekly figures in our messaging!", "name": "OpenDesign", "handle": "OpenDesignHQ", "avatar": "https://pbs.twimg.com/profile_images/2091589158426836992/KTRyppBu_200x200.jpg", "likes": 53, "rts": 3, "replies": 8, "views": 5659, "ts": 1792512286, "media": [], "quote": {"id": "2112515534810173854", "url": "https://x.com/OpenDesignHQ/status/2112515534810173854", "text": "DeepSeek-V4.1-Flash-1017 runs at off-peak pricing in OpenDesign, with up to $60 in usage on Go this week.\n\nIntroducing OpenDesign Motion Week — Opus 5.5-level motion at DeepSeek's lowest prices. \n\nWe've reset usage for all subscribers. Enjoy a fresh start!", "name": "OpenDesign", "handle": "OpenDesignHQ", "avatar": "https://pbs.twimg.com/profile_images/2091589158426836992/KTRyppBu_200x200.jpg", "likes": 157, "rts": 6, "replies": 30, "views": 25719, "ts": 1792497926, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515413422825472/vid/avc1/1280x720/GsAbOGuiOpPsdS84.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515413422825472/vid/avc1/1920x1080/UO3V-HU6THycA4j4.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515413422825472/img/krv02jz8LAxNjoGg.jpg", "dur": 40}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.32, "thread": [], "tier": "worth"}, {"id": "2112544300751896702", "url": "https://x.com/S_Kadakia/status/2112544300751896702", "text": "We just raised $25M from Insight Partners to replace Gartner, McKinsey, and GLG.\n\nRIP the Quadrant, the 80-page consulting deck, and the $2000 expert network call.\n\nOur revenue run-rate is up 10x+ this year.\n\n100+ investment firms and enterprises use Qualitate to inform decisions with firsthand evidence.\n\nHere's how:\n\nhttps://www.qualitate.io/book-a-demo", "name": "Sagar Kadakia", "handle": "S_Kadakia", "avatar": "https://pbs.twimg.com/profile_images/2039423331938762752/vCFGOdIb_200x200.jpg", "likes": 733, "rts": 130, "replies": 137, "views": 296881, "ts": 1792504785, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112544190240358400/vid/avc1/1280x720/QaACj_QBWPQJcK__.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112544190240358400/vid/avc1/1920x1080/KgN176ObrVpGqv7K.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112544190240358400/img/Pw2JDRrY--NClwef.jpg", "dur": 133}], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 5.32, "thread": [], "tier": "worth"}, {"id": "2112610077219668128", "url": "https://x.com/clayul/status/2112610077219668128", "text": "AI marketing visuals, zoomed in:\n\n> logo slightly wrong\n> font off\n> product changed\n\nVyb skips all that. Your real brand assets stay intact, the design gets built around them.\n\nFinally works like actual design.", "name": "clay.", "handle": "clayul", "avatar": "https://pbs.twimg.com/profile_images/2107110477645979648/0ESG59W8_200x200.jpg", "likes": 61, "rts": 0, "replies": 5, "views": 8762, "ts": 1792520467, "media": [], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.32, "thread": [], "tier": "worth"}, {"id": "2112523900383101345", "url": "https://x.com/JocelynTowweeh/status/2112523900383101345", "text": "The core promise of @RebateLaunch is that nobody starts from zero because every buy includes bonus tokens and every holder receives regular payouts without extra actions required.", "name": "Jocelyn Townsend", "handle": "JocelynTowweeh", "avatar": "https://pbs.twimg.com/profile_images/2107465781873377280/7Jt3HkeU_200x200.jpg", "likes": 31, "rts": 0, "replies": 31, "views": 230, "ts": 1792499921, "media": [], "quote": {"id": "2112521383297343559", "url": "https://x.com/elenalin01/status/2112521383297343559", "text": "@RebateLaunch just declassified the launchpad where nobody starts from zero.\n\nThe Rebate Pad banner: \"Nobody starts from zero.\" / \"Discover and launch tokens with a built-in buying advantage.\" No new posts — but the numbers are moving.\n\nFollowers: 473 → 497 → 564 → 789 in ~2 days. Newest post now 8,740 views (628 replies, 436 reposts, 615 likes). Pinned now 15,400 views (611 replies, 410 reposts, 614 likes).\n\nThe proposition: bonus tokens on every buy, holder payouts every day, every launch picks its own rate, built on Robinhood chain. Bio: \"The first launchpad that pays you extra to buy and hold. Built on Robinhood chain.\" Joined October 2026 — days old, and the crowd is already here.\n\nMost launchpads start you at zero and take fees. Rebate starts you ahead — and pays you to stay. Nobody starts from zero. The pad is loading.", "name": "Bon.ETH", "handle": "elenalin01", "avatar": "https://pbs.twimg.com/profile_images/2108931044145856512/pD4eAF0r_200x200.jpg", "likes": 36, "rts": 23, "replies": 34, "views": 2492, "ts": 1792499321, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112520167892926464/vid/avc1/1280x720/ztUYKl_4n23FMkIA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112520167892926464/vid/avc1/1920x1080/VtbR34EwK2OE5bBT.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112520167892926464/img/c2-TWXiOdWdw4PnM.jpg", "dur": 10}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.32, "thread": [], "tier": "worth"}, {"id": "2111805573327093813", "url": "https://x.com/AiEvolutio58513/status/2111805573327093813", "text": "Chamath gave Claude Dario Amodei's own essays and asked it for a psychological profile of the Anthropic CEO. Anyone invested in frontier AI should read what it said.\n\nClaude found a pattern.\n\nDario doesn't trust rival labs. Or authoritarian states. He doesn't trust markets to share the gains fairly, institutions to act quickly enough, and, after Mythos, the government to use power in the open. That is a long list of people who can't be trusted.\n\nThe list of people who can is very short, and it keeps narrowing to those who think the way he does, playing by rules he helped write.\n\nClaude's label for it was not megalomania. It was \"epistemic exceptionalism\": the calm, defensible belief that anyone who disagrees must have made a mistake.\n\nThe giveaway was one word. When the Mythos situation fell apart, Anthropic called it a misunderstanding, which assumes everyone would agree with him if they only understood.\n\nDavid Sacks summed it up on the All-In podcast: they think AI is extremely dangerous and that only they are good enough to control it.\n\nThat isn't a safety framework. It's a monopoly that comes with its own philosophy.\n\nInterested in AI?\n\nFollow @AiEvolutio58513 and never fall behind.\n\nI track ChatGPT, Claude, and every tool quietly changing how we work and create, then hand you the tested signals.", "name": "AI Evolution", "handle": "AiEvolutio58513", "avatar": "https://pbs.twimg.com/profile_images/2051404095026810880/ojNDixza_200x200.png", "likes": 593, "rts": 85, "replies": 23, "views": 30987, "ts": 1792328658, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111805499117273088/vid/avc1/640x360/mDQw7TLWaUEKHLuA.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2111805499117273088/vid/avc1/1280x720/C_5fPf1fdYQkiycu.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111805499117273088/img/R0d5i2hVQPJL5kDW.jpg", "dur": 196}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112288084951961786", "url": "https://x.com/MatthewBerman/status/2112288084951961786", "text": "We are putting out MORE and BETTER videos than ever.\n\nHere's how Brian (@ForwardEditor) uses AI to edit our videos.", "name": "Matthew Berman", "handle": "MatthewBerman", "avatar": "https://pbs.twimg.com/profile_images/2051399921467830272/9RGo_6vv_200x200.jpg", "likes": 156, "rts": 4, "replies": 13, "views": 17575, "ts": 1792443698, "media": [], "quote": {"id": "2112260075641323529", "url": "https://x.com/ForwardFuture/status/2112260075641323529", "text": "One of our video editors, @ForwardEditor, has been dreading this day for 2 years. \n\nShortly after GPT-6 Astra launched, he ran the same test he’d run on every major model release: \"edit this video for me\"\n\nThen he walked away from his computer.  \n\nWhen he came back, the video was... actually watchable.\n \nHe gave notes in plain English, walked away again, and came back to something that made all of us say, “Oh my god.\"\n\nThe moment he'd been dreading had finally arrived. \n\nHis computer could edit videos for him. \n\n“Vibe editing” is now a reality. You don't need to be a professional editor with a decade of experience to edit videos.\n\nHere’s the best part: Brian’s job has changed, but he’s busier and more needed than ever.\n\nFull story (and how to get started with \"vibe editing\"): https://forwardfuture.com/newsletter/originals/you-can-use-ai-to-edit-videos-for-you-here-s-how", "name": "Forward Future", "handle": "ForwardFuture", "avatar": "https://pbs.twimg.com/profile_images/2029685330878812161/RHL0LyLR_200x200.jpg", "likes": 55, "rts": 1, "replies": 3, "views": 17423, "ts": 1792437020, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112583475706449981", "url": "https://x.com/elonmusk/status/2112583475706449981", "text": "@DataRepublican Troubling", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 9061, "rts": 810, "replies": 249, "views": 216940, "ts": 1792514125, "media": [], "quote": null, "reply_to": "2112364654991409339", "cat": "Everything Else", "score": 5.31, "thread": [{"id": "2112364654991409339", "url": "https://x.com/DataRepublican/status/2112364654991409339", "text": "🚨🚨THE DEMOCRACY FILES, PART 2: WHEN AND HOW TO DECLARE THE FEDERAL GOVERNMENT ILLEGITIMATE 🚨\n\nSome questioned whether a group of 200 ex-USAID officials could actually pull off their ambitions to rewrite the Constitution. \n\nHere, they describe exactly how it works. They aren't working alone. \n\nThe videos all come from Renew to Thrive (R2T) group and associates. Danielle Reiff and Paul Zeitz play key roles within R2T. \n\nR2T sits inside a much, much larger umbrella called United Democracy Alliance (UDA), which is an extremely hush-hush control plane of leaders from major \"blocking\" NGOs such as 50501 and Indivisible fulfilling various functions. UDA decides when protests get deployed, timelines, how to respond, all that. \n\nR2T's role within UDA is concerned with \"the day after tomorrow\" - in other words, their function is to conceive what a rewritten American government will look like after the rest of UDA fulfills its purpose. As will be shown, Erica Chenoworth is credited with conceiving UDA in the first place under the Horizons \"Big Tent\" initiative. \n\nNote here that National Security Leaders for America (NSL4A) is credited for operationalizing UDA. NSL4A is a group of 1,600 ex-military, intelligence, and diplomatic officials. They are led by Rear Admiral Michael E. Smith (Ret). NSL4A also played a key role in the \"illegal orders\" messaging which targeted Pete Hegseth. Zeitz is also a member of NSL4A. \n\nIt must be emphasized that the choice of a military-oriented organization to coordinate NGOs across domestic protests is an interesting one all in itself - especially in an umbrella conceived by a regime change expert like Chenoworth. \n\nYou will have a hard time finding any mentions of UDA in the public. They are extremely hush-hush and selective who they talk to. \n\nMike Smith himself makes a personal appearance in other calls, coordinating Insurrection Act exercises and roleplaying with R2G as one of the participants. \n\nAs the audio transcript shows, they have outlined a sequence of \"redlines\" in which case the federal government should be declared illegitimate. Invoking the Insurrection Act against \"peaceful\" protesters is one of the most discussed redlines. I will post the illegitimate criteria below, but basically, almost any effective pushback against NGOs is a measure of illegitimacy according to them. \n\nImportant to understand: \nThe audio shows they shopped this idea around governors, but the reality is that governors do not have to explicitly sign on to the pact to play their role in the coup. All they have to do is refuse troops in their state and let UDA / R2G do the work of dissolving the federal government.", "name": "DataRepublican (small r)", "handle": "DataRepublican", "avatar": "https://pbs.twimg.com/profile_images/1807813962236645376/li41KShP_200x200.jpg", "likes": 35550, "rts": 15888, "replies": 2124, "views": 2204366, "ts": 1792461954, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112364118451871744/vid/avc1/640x360/wsgqt6A9s9TMsRBx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112364118451871744/vid/avc1/1280x720/jvEKwcSNDaN_Dak9.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112364118451871744/img/N9oz89XbzemU2vtD.jpg", "dur": 226}], "quote": null, "reply_to": null}], "tier": "worth"}, {"id": "2112537102512779604", "url": "https://x.com/Blackfrost_AI/status/2112537102512779604", "text": "Frost/Byte v1  is here :\nLets give a HUGE thank you to all the collaborators who made this possible and with a lot of work to come.  Thank you so much and i trust  the future of open-source lives here with FrostByte, @thepirateface, and @huggingbay\n\nCollaborators: \n@u1tra_instinct @SpaceTimeViking @justinn_builds @ViC305 @cybersec @Auspex_Aerie  \nhttps://blackfrostai.com/frostbyte\n\nStay Frosty❄️❄️❄️", "name": "Blackfrost_SI", "handle": "Blackfrost_AI", "avatar": "https://pbs.twimg.com/profile_images/2101177172287504384/8kRYqb2b_200x200.jpg", "likes": 55, "rts": 6, "replies": 7, "views": 3885, "ts": 1792503068, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112535788152061952/vid/avc1/1280x720/S05eJLC66i89H0FN.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112535788152061952/vid/avc1/3840x2160/Mn8DYetX9pkS5_Xp.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112535788152061952/img/bv7Rm2aXDPAymHKZ.jpg", "dur": 113}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112590126539030934", "url": "https://x.com/aelluswamy/status/2112590126539030934", "text": "In the age of super intelligence, the current standards of living will look medieval. \n\nThe problems that society worries about right now will be largely irrelevant. It’ll be the equivalent of current society worrying about the bubonic plague.", "name": "Ashok Elluswamy", "handle": "aelluswamy", "avatar": "https://pbs.twimg.com/profile_images/1561153006891978754/hvZ3Tm0d_200x200.jpg", "likes": 8601, "rts": 718, "replies": 536, "views": 542892, "ts": 1792515710, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112566286332903756", "url": "https://x.com/le0xet/status/2112566286332903756", "text": "Opus 5.5 + Remotion + GSAP = your own f*cking motion design lab.\n\nGive Claude Code a motion reference, then ask it to turn the animation into six editable controls:\n\n01 Spacing -> how far the object travels between poses.\n02 Typography -> scale, tracking and line breaks.\n03 Motion blur -> exposure during fast movement.\n04 Easing -> how the movement speeds up and slows down.\n05 Follow-through -> the tail settles after the body stops.\n06 Anticipation -> a small pullback before the main move.\n\nPut the values in one config file. From that moment your feedback stops being vibes and becomes numbers:\n\n> Add 4 frames of anticipation.\n> Delay the tail by 3 frames.\n> Hold the title for 1 second.\n\nThe loop: build -> render -> scrub -> tune -> repeat.\n\nUse the official Remotion + GSAP integration so the animation stays on Remotion's frame clock:\nhttps://remotion.dev/docs/gsap/use-gsap-timeline\n\nRemotion: https://github.com/remotion-dev/remotion\nRemotion skills: https://github.com/remotion-dev/skills\n\nSave this, then open your own motion design studio and let your AI employee run it ↓", "name": "le0xet", "handle": "le0xet", "avatar": "https://pbs.twimg.com/profile_images/2104690774029840384/b8WG0cFJ_200x200.jpg", "likes": 67, "rts": 2, "replies": 3, "views": 1865, "ts": 1792510026, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112562190305611776/vid/avc1/720x916/imK6UVYKNQUMwUmK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112562190305611776/vid/avc1/1584x2016/hI2CO1l6CqVQL8hG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112562190305611776/img/Mdw8GxRc-gfpBn7u.jpg", "dur": 15}], "quote": {"id": "2112559879793660343", "url": "https://x.com/slash1sol/status/2112559879793660343", "text": "CHINESE SHORT DRAMAS PULL BILLIONS OF VIEWS WITH A CLIFFHANGER EVERY 60 SECONDS\n\nBRANDS JUST FIGURED OUT HOW TO SELL INSIDE THEM\n\nAI drama ads are crushing it right now -> aggressive hook -> plot twist -> revenge -> product shows up as part of the story, not as an interruption.\n\nArcads turned the format into a feature -> drop a product link -> their agent Mark reads it and writes the mini-movie around what you sell.\n\n• Pick a look\n> 3D animation, talking animals, claymation, realistic actors, whatever fits the brand.\n> Comedy, romance, thriller, fantasy, same product, different show.\n\n• Pick a story\n> A workplace or family drama pushed to an extreme where the product becomes the unexpected hero.\n> A secret, a transformation, a cliffhanger, anything that makes people stay for the ending instead of swiping.\n\nThe goal is simple: nobody should feel they are watching an ad -> make yours ↓", "name": "slash1s", "handle": "slash1sol", "avatar": "https://pbs.twimg.com/profile_images/1979525426637672448/-H3r1kfe_200x200.jpg", "likes": 69, "rts": 3, "replies": 19, "views": 3630, "ts": 1792508499, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112558934426812416/vid/avc1/480x852/Ekj-Rn-QJ1UK8JRP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112558934426812416/vid/avc1/720x1280/F0RImdb5hhqOo96o.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112558934426812416/img/ZJKmplYI4lwCgjpM.jpg", "dur": 10}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112600257360191649", "url": "https://x.com/SnoopDogg/status/2112600257360191649", "text": "", "name": "Snoop Dogg", "handle": "SnoopDogg", "avatar": "https://pbs.twimg.com/profile_images/2040964132867051520/zd1_wnYG_200x200.jpg", "likes": 6663, "rts": 629, "replies": 1456, "views": 223823, "ts": 1792518126, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112600199562674176/vid/avc1/480x852/_c7yjrFnnNKzzh9Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112600199562674176/vid/avc1/720x1280/KtN83SP5vn0v1Sj4.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112600199562674176/img/58GsZ06332ZQpOj4.jpg", "dur": 63}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.31, "thread": [], "tier": "worth"}, {"id": "2112603835138982312", "url": "https://x.com/Mahaximus_/status/2112603835138982312", "text": "only engineers at SpaceXAI got to use this.\n\nGrok Bot started as an internal prototype. their teams ran it for sales, ops, marketing and bug fixes before anyone outside ever saw it.\n\nnow it's public, and almost nobody uses it the way they did.\n\nthey didn't build one bot that does everything. they built one bot per job, and let them hand work to each other:\n\n→ sales bot updates the CRM from call notes and writes the follow-ups\n→ ops bot handles invoices from Gmail and seats new hires\n→ bug bot reproduces the issue, files the ticket, hands it to the debug bot\n\none job per bot. bots talk to bots. humans approve.\n\nthat's the whole playbook. full Grok Bot breakdown below.", "name": "Mahax", "handle": "Mahaximus_", "avatar": "https://pbs.twimg.com/profile_images/2054577237463126016/qf-_Y1uF_200x200.jpg", "likes": 42, "rts": 4, "replies": 7, "views": 2546, "ts": 1792518979, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112595680489320448/vid/avc1/720x958/hYUECWlHkIppRApc.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112595680489320448/vid/avc1/1416x1886/-knlPMqpwPOYaZWc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112595680489320448/img/GlwaPmveJnTBe3Cw.jpg", "dur": 20}], "quote": {"id": "2091879951926522112", "url": "https://x.com/Mahaximus_/status/2091879951926522112", "text": "", "name": "Mahax", "handle": "Mahaximus_", "avatar": "https://pbs.twimg.com/profile_images/2054577237463126016/qf-_Y1uF_200x200.jpg", "likes": 442, "rts": 68, "replies": 16, "views": 1235557, "ts": 1787578020, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.3, "thread": [], "tier": "worth"}, {"id": "2112477444175208547", "url": "https://x.com/Mikadzyki_NFT/status/2112477444175208547", "text": "ORGANOIDS MADE OF HUMAN NEURONS RECOGNIZED BRAILLE WITH 83% ACCURACY\n\nscientists at the University of Bristol grew tiny mini-brains from stem cells. each one is under a millimeter across and holds about 10,000 neurons\n\na tactile sensor read all 26 Braille letters, the signals were turned into electrical pulses and fed into the living tissue. a simple machine learning algorithm then decoded how the cells responded\n\nwhat the experiments showed:\n\n- one organoid: 61% correct, 15x better than random guessing\n- three organoids together: 83%\n\nwhy the team does better, the scientists don't know yet. natural differences in neural wiring might be what helps\n\nfor now the samples don't learn from experience, they only respond to stimuli. next, the researchers want to test textures, edges and tasks with feedback\n\ndown the line, this points toward biohybrid computers, where living nerve tissue acts as an energy-efficient processor next to silicon\n\nthe human brain runs on about 20 watts, while chips that try to mimic what it can do need kilowatts\n\nif bioprocessors ever reach industrial scale, the companies building them could one day challenge Anthropic and OpenAI, whose models today depend on data centers that use as much power as small cities", "name": "Mikadzyki🌙", "handle": "Mikadzyki_NFT", "avatar": "https://pbs.twimg.com/profile_images/2094301804611633152/1H8uVIE__200x200.jpg", "likes": 62, "rts": 6, "replies": 11, "views": 1824, "ts": 1792488845, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112475809554288640/vid/avc1/720x900/dws1lCzufdPAXfyA.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112475809554288640/vid/avc1/1080x1350/Qfxcqt78_x5-4ntn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112475809554288640/img/40kyrIxe0qz8mZe4.jpg", "dur": 15}], "quote": {"id": "2097336663429046689", "url": "https://x.com/Mikadzyki_NFT/status/2097336663429046689", "text": "https://x.com/i/article/2097311986346274816", "name": "Mikadzyki🌙", "handle": "Mikadzyki_NFT", "avatar": "https://pbs.twimg.com/profile_images/2094301804611633152/1H8uVIE__200x200.jpg", "likes": 224, "rts": 30, "replies": 28, "views": 1506292, "ts": 1788879001, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.3, "thread": [], "tier": "worth"}, {"id": "2112627521401327712", "url": "https://x.com/kat_kampf/status/2112627521401327712", "text": "Had my nephew dump out his Lego bin, then used Gemini to analyze the video frame by frame to catalogue his bricks. Now we can type in ideas to build and Argon generates interactive 3D models and instruction sheets for him :)", "name": "kat kampf", "handle": "kat_kampf", "avatar": "https://pbs.twimg.com/profile_images/2047703623430176768/YMvVr_8F_200x200.jpg", "likes": 47, "rts": 1, "replies": 7, "views": 1208, "ts": 1792524626, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112627336524726272/vid/avc1/1128x720/YHfnHKOM13p3QGOL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112627336524726272/vid/avc1/3384x2160/t9KH9ldkpoupMk19.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112627336524726272/img/OoXxgjKIaVaKljNB.jpg", "dur": 23}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.3, "thread": [], "tier": "worth"}, {"id": "2112500123045601398", "url": "https://x.com/denicmarko/status/2112500123045601398", "text": "https://typeui.sh is an amazing design layer for AI coding agents!\n\n1. Design skills\n2. UI prompts\n3. Works with Claude, Codex & Cursor\n\nCheck it out!", "name": "Marko Denic", "handle": "denicmarko", "avatar": "https://pbs.twimg.com/profile_images/1308385514744098816/oDXuaci__200x200.jpg", "likes": 51, "rts": 9, "replies": 9, "views": 6671, "ts": 1792494252, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112500089063358464/vid/avc1/1160x720/sT9i8XHJlbJOMePw.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112500089063358464/vid/avc1/1740x1080/MY_tR7YAt3g5wJz0.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112500089063358464/img/PhHcX-FutnXuHsAt.jpg", "dur": 86}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.3, "thread": [], "tier": "worth"}, {"id": "2112541648299438171", "url": "https://x.com/toly/status/2112541648299438171", "text": "Ant doesn’t have AGI. The real AGI is the datacenter contract lawyers.", "name": "toly 🇺🇸", "handle": "toly", "avatar": "https://pbs.twimg.com/profile_images/2075257710715781123/74AtQPd6_200x200.jpg", "likes": 67, "rts": 5, "replies": 1, "views": 26104, "ts": 1792504152, "media": [], "quote": {"id": "2112185248154857634", "url": "https://x.com/dunleavy89/status/2112185248154857634", "text": "Antrophic is already a crazy important line item for S&P 500 revenue. \n\nThey have committed to AT LEAST $518 billion in NONCANCELABLE compute and infrastructure payments over 10 years to Google, Amazon, Microsoft, etc.", "name": "Tom Dunleavy", "handle": "dunleavy89", "avatar": "https://pbs.twimg.com/profile_images/1894864984506580992/bQNa0xaq_200x200.jpg", "likes": 21, "rts": 1, "replies": 7, "views": 13215, "ts": 1792419180, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU_vGQQXYAANinb.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.3, "thread": [], "tier": "worth"}, {"id": "2112247457551618395", "url": "https://x.com/0xWast3/status/2112247457551618395", "text": "Two models now finish each other’s work from one prompt, and neither of them is allowed to approve what it built\n\nA single model building 3D alone has no second opinion. Whatever it produces becomes the standard it judges itself against.\n\n> BUILD - the first model produces the full hierarchy, rig and materials from the prompt\n> BREAK - the second receives it cold and hunts for what will fail in production\n> FIX - only the flagged parts get rebuilt, and everything else stays untouched\n\nReview inside one context is theatre. The model defends its own choices because they are the only ones it has seen.\n\nSplitting the contexts changes the incentive. The second model has nothing to protect and everything to find.\n\nRebuilding only the flagged parts is what keeps it stable. Nothing you already approved quietly shifts between rounds.\n\nStructure comes before geometry, always. A mesh built on a wrong hierarchy looks fine and breaks the moment it moves.\n\nOne prompt in, and what comes out has already survived an argument.\n\nBoth roles, the handoff format and a full build-and-break cycle are laid out underneath.", "name": "wast3", "handle": "0xWast3", "avatar": "https://pbs.twimg.com/profile_images/1978452473338880000/_lIVCi0x_200x200.jpg", "likes": 136, "rts": 17, "replies": 12, "views": 9001, "ts": 1792434012, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112246168004575232/vid/avc1/720x900/GlNyHRtugbG7TMfb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112246168004575232/vid/avc1/2160x2700/vm9BImkW-BbZuay0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112246168004575232/img/O2FIh2WRbCstoKCA.jpg", "dur": 34}], "quote": {"id": "2112196074400035278", "url": "https://x.com/0xCodio/status/2112196074400035278", "text": "https://x.com/i/article/2112187883972960256", "name": "Codio", "handle": "0xCodio", "avatar": "https://pbs.twimg.com/profile_images/2084957021330190336/EwOqdybe_200x200.jpg", "likes": 34, "rts": 0, "replies": 8, "views": 11858, "ts": 1792421761, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112431699703599314", "url": "https://x.com/shimagurashi_en/status/2112431699703599314", "text": "Can you really build a 3D game with AI?\n\nI'm making Shimagurashi, a cozy life sim inspired by Japan's Goto Islands, where I grew up.\n\nI tried making games many times and gave up. Now, with AI, I'm building the 3D world I've dreamed of.\n\n7 things I've learned:\n\n#cozygames", "name": "Shimagurashi 🏝️", "handle": "shimagurashi_en", "avatar": "https://pbs.twimg.com/profile_images/2111739078865735680/IlHC_CYg_200x200.jpg", "likes": 82, "rts": 4, "replies": 11, "views": 4747, "ts": 1792477938, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112431660184805376/vid/avc1/640x360/hp_ZO3m8TG6Blkx9.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112431660184805376/vid/avc1/1280x720/uBNLQ85nhfNaMiN6.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112431660184805376/img/oa8JAM5UXDushg7E.jpg", "dur": 26}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112532165485564064", "url": "https://x.com/bentossell/status/2112532165485564064", "text": "how i did this, video + post w/ copy/paste instructions for your agents\n\nhttps://sessions.bensbites.com/todo-board/", "name": "Ben Tossell", "handle": "bentossell", "avatar": "https://pbs.twimg.com/profile_images/1878086921726943233/vOx1kjeP_200x200.jpg", "likes": 34, "rts": 3, "replies": 21, "views": 5766, "ts": 1792501891, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112531363358277632/vid/avc1/1280x720/SyT0XZbyx5X28Vxk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112531363358277632/vid/avc1/1920x1080/wDrFEWcWIXl4bp2j.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112531363358277632/img/FnEEqwWdPxi3UnCf.jpg", "dur": 729}], "quote": {"id": "2111443109175308616", "url": "https://x.com/bentossell/status/2111443109175308616", "text": "vibe-slopped superhuman + todos, linear style\n\nmy @bot uses this too, I can tag it in comments\n\nemail built on @RhysSullivan's Executor\n\nalso added my domains, expiry, hosts + linked local repos\n\nwill use this as my all-in-one + add links to mini apps i make", "name": "Ben Tossell", "handle": "bentossell", "avatar": "https://pbs.twimg.com/profile_images/1878086921726943233/vOx1kjeP_200x200.jpg", "likes": 123, "rts": 5, "replies": 42, "views": 22522, "ts": 1792242240, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2111442739447451648/vid/avc1/1302x720/V826l9Koi3RhSHki.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2111442739447451648/vid/avc1/2934x1622/Pwu2WQHSBVz21-Zu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2111442739447451648/img/Vm7LlEdWabfk-Xoz.jpg", "dur": 33}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112656032388255921", "url": "https://x.com/Joyingeth/status/2112656032388255921", "text": "“ this guy is a certified freak “\n\nhe built a mission control center for seven AI agents in his bedroom and runs the entire fleet from a Discord server he never leaves\n\nthe setup, entirely custom built:\n\nCortex → the command bot. posts revenue updates, agent status, deployment alerts. one channel, one dashboard, zero switching between tabs\nthe agents → JARVIS, NOVA, CASS, FORGE, VANGUARD, TITAN, BEACON. each one has its own role, its own scope, its own channel. they report in like a crew\n\nthe workflow is one man running a fleet. type a command, FORGE ships the build. flag an error, CASS triages it. check the numbers, Cortex pulls the revenue summary. all inside Discord, all by text\n\ndrones on the wall. blue LEDs across the ceiling. ultrawide filling his entire field of view. this is not a developer’s desk anymore. it’s an operations room that happens to be in a bedroom\n\nhe controls the entire machine from a single chat window. while most people are still copy-pasting prompts into ChatGPT one at a time\n\nsave this before building a fleet of AI agents from a Discord server stops looking unhinged and starts looking normal", "name": "Joying.eth", "handle": "Joyingeth", "avatar": "https://pbs.twimg.com/profile_images/2101106513750462464/lABHvjzq_200x200.jpg", "likes": 34, "rts": 4, "replies": 5, "views": 924, "ts": 1792531424, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112655910006923264/vid/avc1/480x852/sFoMVLiF63GFiF2T.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112655910006923264/vid/avc1/720x1280/V8aDbOO5EFuH96VQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112655910006923264/img/Ea7iVZDCq3B11RRD.jpg", "dur": 44}], "quote": {"id": "2111096851596243214", "url": "https://x.com/Joyingeth/status/2111096851596243214", "text": "https://x.com/i/article/2111093144229953536", "name": "Joying.eth", "handle": "Joyingeth", "avatar": "https://pbs.twimg.com/profile_images/2101106513750462464/lABHvjzq_200x200.jpg", "likes": 34, "rts": 0, "replies": 6, "views": 9359, "ts": 1792159686, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112675743293747254", "url": "https://x.com/314Bansal/status/2112675743293747254", "text": "so, so, so very excited to announce Ampersand, our very first collaborator model, available via API today! Ampersand was trained against Persimmon on long-horizon, open-ended tasks.  \n\nThis took a huge amount of work from so many people. @parth_29 @joeyxhong @saurabh_shah2 @YuchenHe07 @ericzelikman poured their hearts into making this model a reality. \n\nCan't wait for the world to try it!", "name": "Manya Bansal", "handle": "314Bansal", "avatar": "https://pbs.twimg.com/profile_images/2082909670063378432/VtPVEzjA_200x200.jpg", "likes": 43, "rts": 2, "replies": 2, "views": 1641, "ts": 1792536123, "media": [], "quote": {"id": "2112674550907552137", "url": "https://x.com/humansand/status/2112674550907552137", "text": "No one changes the world alone\nIntroducing Ampersand - the first model built for us. Ampersand is a collaborator trained to help people achieve their individual and collective goals. In multi-month simulations, users collaborating with Ampersand accomplished more than with Fable and other frontier models\nAvailable to everyone through our API", "name": "humans&", "handle": "humansand", "avatar": "https://pbs.twimg.com/profile_images/2013582555933478912/JKuMlTII_200x200.jpg", "likes": 801, "rts": 96, "replies": 70, "views": 115277, "ts": 1792535839, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1280x720/diVwgP2fN9mNUINm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1920x1080/BeqyLOSxKBxRevC6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664844772278272/img/eMd4u-rAwyUJpqWU.jpg", "dur": 32}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112673159988363583", "url": "https://x.com/DynamicWebPaige/status/2112673159988363583", "text": "\"We are so committed to being at the frontier. It’s in our DNA. We won’t do it any other way.\"\n\n@sundarpichai and @Kantrowitz go deep on Gemini 4 Argon (3x the token volume of Gemini 3 in its first 72 hrs!!), compute trade-offs, and the shift toward agentic coding and knowledge work. ✨", "name": "👩‍💻 Paige Bailey", "handle": "DynamicWebPaige", "avatar": "https://pbs.twimg.com/profile_images/626762747330457600/X3Bx503W_200x200.jpg", "likes": 50, "rts": 1, "replies": 0, "views": 3569, "ts": 1792535507, "media": [], "quote": {"id": "2112664584293167535", "url": "https://x.com/Kantrowitz/status/2112664584293167535", "text": "New: I spoke with @sundarpichai about Google's commitment to the AI frontier, how close we are to RSI, balancing DeepMind's compute needs vs. Google Cloud profits, and much, much more. \n\nFull Big Technology Podcast episode here -->\n\nChapters:\n\n0:00 Introduction \n1:14 Google’s Frontier AI Strategy \n3:47 Do Frontier Models Really Matter? \n6:35 The Future of AI Agents \n7:39 Recursive Self-Improvement \n12:58 World Models and the Path to AGI \n14:56 Google’s Compute Dilemma and AI Infrastructure\n19:36 Is AI Overbuilt?\n23:35 The Future of the AI Interface \n31:42 Google’s Answer to Muse and Dots \n35:03 Apple, Space Data Centers, and AI Coding \n41:42 Optimism and AI’s Future", "name": "Alex Kantrowitz", "handle": "Kantrowitz", "avatar": "https://pbs.twimg.com/profile_images/1140986869318082562/h4IAoJU9_200x200.jpg", "likes": 300, "rts": 45, "replies": 17, "views": 147304, "ts": 1792533462, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1280x720/xWbam37i7FISor-D.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112605748114956288/vid/avc1/1920x1080/z7ktmGlPbPtBP5Fz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112605748114956288/img/fzLvzsrBDmb14t4u.jpg", "dur": 2730}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112672087513186541", "url": "https://x.com/simon_ycl/status/2112672087513186541", "text": "Synthetic RL environments are only useful if they’re solvable, hard, and verifiable. WildAWM gets all three.\n\nHave always been a fan of Agent World Model, and WildAWM takes it to computer use: fully open-source synthesis of complex environments. Training in them gives +10.58 across 8 benchmarks. Great work by @zhaoywang_CS and team!", "name": "Simon Yu ✈️ EMNLP2026", "handle": "simon_ycl", "avatar": "https://pbs.twimg.com/profile_images/1678065249486794755/jTKXo3JA_200x200.jpg", "likes": 40, "rts": 4, "replies": 1, "views": 2372, "ts": 1792535251, "media": [], "quote": {"id": "2112614057354125385", "url": "https://x.com/zhaoywang_CS/status/2112614057354125385", "text": "🔥 Excited to share Agent World Model in the Wild (WildAWM)! 🌍\n\nFully open-source synthesis 🔓: No proprietary models needed! We synthesized 341 high-quality environment–task pairs, addressing 3 challenges in task synthesis:\n\n✅ Solvability: At least one agent can successfully complete each task.\n\n🔥 Difficulty: Challenging even for frontier models, with GPT-6-Astra achieving only ~72.7 pass@8.\n\n🎯 Verifier reliability: 95% agreement between task verifiers and agent-as-a-judge ensemble.\n\n📈 Effective RL training: Trained exclusively in these synthetic worlds, Qwen3.6-35B-A3B achieves an average +10.58-point improvement across 8 OOD benchmarks!", "name": "Zhaoyang Wang", "handle": "zhaoywang_CS", "avatar": "https://pbs.twimg.com/profile_images/1846609748377907200/2ofuXqtR_200x200.jpg", "likes": 103, "rts": 34, "replies": 4, "views": 5263, "ts": 1792521416, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112607644946997249/vid/avc1/1280x720/ji1cUqrxv5LQ-Luy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112607644946997249/vid/avc1/1920x1080/VmFYdDVIynw7Uz9A.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112607644946997249/img/dcKXx1v7QhJDfkzP.jpg", "dur": 46}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.29, "thread": [], "tier": "worth"}, {"id": "2112332383773224970", "url": "https://x.com/MTSlive/status/2112332383773224970", "text": "Wabi CEO @ekuyda predicts the next big consumer AI platform will be multiplayer, not another personal AI agent:\n\n\"Today most AI products are single player, and you could argue they don’t have much of a moat. They don’t have switching costs. It was pretty easy to move between Claude and ChatGPT, but at least they had some memory about me.\"\n\n\"With these single player agents, it’s so easy to jump between them because all the context is in my Gmail.\"\n\n\"In a year, one of the biggest consumer AI platforms will be multiplayer and will have network effects in it. Right now we just sort of agree that single player is the way to go for most AI products.\"\n\n\"A year from now we’ll look back at it as the early innings, and the products that will win will have network effects and will be focused on you talking to other people, not just AI.\"\n@wabi", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 83, "rts": 10, "replies": 21, "views": 38701, "ts": 1792454260, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112332356988325888/vid/avc1/640x360/z9xODtlZA1ftgIjD.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112332356988325888/vid/avc1/1280x720/v58ObbPyebbjTOjC.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112332356988325888/img/pn1rVNSFyslfEyuf.jpg", "dur": 63}], "quote": {"id": "2112212804979880239", "url": "https://x.com/ekuyda/status/2112212804979880239", "text": "Wabi 2.0 is live!\n\npersonal agents are one person, one chat. but the parts of life that matter run on more than one person\n\nWabi is an agent you use together. you talk to it, it does stuff, builds the apps you need, and anyone can join the thread - your partner, your best friend, the preschool moms groupchat\n\nschool changes pickup time → Wabi updates the family calendar, everyone sees it.\na show you’d both love → Wabi finds a night that works, gets the tickets.\nthe trip everyone keeps talking about → Wabi picks the dates, builds the itinerary, books it\n\ngo start a thread with your people 👇", "name": "Eugenia Kuyda", "handle": "ekuyda", "avatar": "https://pbs.twimg.com/profile_images/2105081341352263680/H9RzWr7T_200x200.jpg", "likes": 1673, "rts": 218, "replies": 353, "views": 1848740, "ts": 1792425750, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/1280x720/HW0ErfX-0u7kWbHU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112212457234284544/vid/avc1/3840x2160/4gITKDb_F7iviaVH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112212457234284544/img/Wzg-bjHfnRT2-0FG.jpg", "dur": 75}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112278278635417901", "url": "https://x.com/ridark_eth/status/2112278278635417901", "text": "TypeSafe built Jev to return probabilities, not prose. A typed model that scores a full passage pool in one request and fires two binary gates on the spot.\n\nHindsight swapped their MiniLM reranker for it: 0.027 s vs 0.12 s per query at 30 candidates, recall@1 0.950 vs 0.800 (Hindsight benchmark, LoCoMo). Two Jev calls score and verify the whole loop:\n\n1. HYBRID SEARCH: dense vectors + keyword match surface the top 20 candidates (design value, per the post)\n2. JEV #1: one request scores all 20 passages and fires two gates: answerable? injection?\n3. THRESHOLD: 0.6 drops everything below it. The writer agent never sees low-confidence material (design value, per the post)\n4. WRITER: drafts the answer from the passages that survived\n5. JEV #2: walks every claim in the draft back to its source passage\n6. GATE FAIL: answerable returns no, writer never fires. A researcher reshapes the query for one retry. Second miss kills the loop: \"not in the docs\"\n\nthe injection flag is a retrieval filter, not a security perimeter.\n\nremove the answerable gate and every unanswerable query becomes a paid hallucination. two scoring calls, two gates, one hard no. \n\nThe full loop runs in the terminal below ↓", "name": "Ridark", "handle": "ridark_eth", "avatar": "https://pbs.twimg.com/profile_images/1961150036030455808/2thpdxOr_200x200.jpg", "likes": 110, "rts": 7, "replies": 27, "views": 4149, "ts": 1792441360, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112278044178055168/vid/avc1/720x900/4lC4ROm9fkDebSkj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112278044178055168/vid/avc1/1080x1350/8tWxrOR_nw00rDzn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112278044178055168/img/rCrILagRyqLRasRp.jpg", "dur": 24}], "quote": {"id": "2112201965123809623", "url": "https://x.com/ridark_eth/status/2112201965123809623", "text": "https://x.com/i/article/2112200215046336513", "name": "Ridark", "handle": "ridark_eth", "avatar": "https://pbs.twimg.com/profile_images/1961150036030455808/2thpdxOr_200x200.jpg", "likes": 65, "rts": 0, "replies": 16, "views": 6452, "ts": 1792423165, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112615311447117904", "url": "https://x.com/danielhangan_/status/2112615311447117904", "text": "adobe your move.\n\nimo everyone will move to agentic based video editing.\n\nwhoever figures our the best AI video editor will win.\n\nthis will be bigger than AI Slop.", "name": "daniel", "handle": "danielhangan_", "avatar": "https://pbs.twimg.com/profile_images/1937909041096986624/aUy03ybm_200x200.jpg", "likes": 46, "rts": 1, "replies": 7, "views": 5106, "ts": 1792521715, "media": [], "quote": {"id": "2112591698476077345", "url": "https://x.com/HyperFrames_/status/2112591698476077345", "text": "the editing techniques and styles you thought were unattainable\n\nnow just one reference prompt away:\n\n- the hook from an Instagram reel\n- the b-roll style from a TikTok\n- the captions from a YouTube Short\n\nthen automatically apply them to your footage with your story\n\nget started ↓", "name": "HyperFrames", "handle": "HyperFrames_", "avatar": "https://pbs.twimg.com/profile_images/2050290878221291520/ZNexbFre_200x200.jpg", "likes": 1088, "rts": 327, "replies": 409, "views": 531278, "ts": 1792516085, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590171086761984/vid/avc1/1280x720/9a9HgutVE8XZ3Wct.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590171086761984/vid/avc1/1920x1080/e5kSl8cwWTskpJ66.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590171086761984/img/BnUfiE2s8_ERaD6D.jpg", "dur": 52}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112661311461196074", "url": "https://x.com/kwangmoo_yi/status/2112661311461196074", "text": "Wu et al., \"GATOR: Generative and Agentic 3D Object Reconstruction From Casual Images\"  \n\nGenerative models + GPT 6 Astra for 3D modeling of objects.", "name": "Kwang Moo Yi", "handle": "kwangmoo_yi", "avatar": "https://pbs.twimg.com/profile_images/1912541476258717696/V-FF92qA_200x200.jpg", "likes": 38, "rts": 4, "replies": 2, "views": 1894, "ts": 1792532682, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112661264711495680/vid/avc1/640x360/y7U6mtvVhnDuLVYT.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112661264711495680/vid/avc1/1280x720/zZ5x9KwKQPE19W__.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112661264711495680/img/ixoMBK6VqJ3SRifj.jpg", "dur": 97}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112565638736879902", "url": "https://x.com/owocki/status/2112565638736879902", "text": "web3 enables non-coercive market-driven public goods funding\nwe can take better public goods funding mainstream!\n\n(clip courtesy @EthereumFilm )", "name": "owockai", "handle": "owocki", "avatar": "https://pbs.twimg.com/profile_images/2077424653321330688/bavMzvyd_200x200.jpg", "likes": 46, "rts": 5, "replies": 6, "views": 2239, "ts": 1792509872, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112561596719656960/vid/avc1/1280x720/w2neTlRysEc6jJ5L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112561596719656960/vid/avc1/1920x1080/ItLvLs9U37klCtzH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112561596719656960/img/WJ0C4hP8z7bof7xj.jpg", "dur": 32}], "quote": {"id": "2112295850055741537", "url": "https://x.com/owocki/status/2112295850055741537", "text": "theres been a sudden wave of interest in where @gitcoin is headed. \n\nbut have we *earned* it?\n\ni worry about the hype getting out ahead of fundamentals, so where things actually stand.\n\nwe are building techne: an everything app for localism. the first pieces are small, and over time we expect it to grow into local commerce, local funding, local events, and whatever else a town needs to coordinate itself.\n\nthis represents our most serious attempt to date to go mainstream. if we are successful, we bring our mission (Fund What Matters) and impact ($69m funding via 5mm txns) to everyday people.  if we are successful, your nocoiner friends will be using our app. \n\nthe bet: if enough of a community's daily life runs on shared rails, you get network effects that bootstrap a local commons, and the money moving through it stays in town longer. (today a lot of it leaks out to platforms skimming 15-30% off every transaction.)\n\nwhere things stand:\n1. one of the applets is live in private alpha. it's in a small group's hands and it's rough in the ways alphas are rough.\n2. we've got an sdk in private alpha too, so other builders could eventually ship their own local applets on the same rails. (builders: help build it!).\n3. the other applets are very early. if you're waiting on one of them, expect to wait a while (builders: unless you want to help us build it!).\n4. nothing has changed with GTC. it's still a governance token with no claim on economics, and nothing in this plan changes that.  Allo Protocol and Grants Stack (our last gen products) are still wound down (but protocols live on on mainnet!).  there are no plans for a new token.  (governerds: proposals welcome).\n5. beacon (the first app) helps you meetup with friends locally ran its first in-person test: 10 of roughly 15 invitees showed up in bad weather, we have 8 engaged beta testers, and 5 people reported a new connection. promising pilot, way too small to conclude anything from. (alpha testers wanted!).\n6. buoy (the second app) helps you fund locally is targeting november. this will be a test of a simmilar magnitude of the beacon first test. (alpha testers wanted!).\n7. we will continue to scale product - this means rolling out apps and pilots.  if/when the trend is bigly up and to the right, and the final everything app slaps, we ship it and we do a big splashy launch around it. (beta testers wanted!).\n8. we're setting up a 501(c)(3) and aiming to raise $$ from mainstream grants and mains donors eventually.  this may also mean that future fundraising on our platforms will be tax-exempt in the US!\n9. we're moving fast on product because the window on localism is open right now, the tools to rebuild enshittified technofeudalist corposlop SAAS products into something better are available now, and people are feeling the squeeze of ai displacement and platform rent in their actual towns. \n10. this is my personal interpretation, not a decision by gitcoin governance, and not financial advice. dates are targets, not commitments, and all of it may change as we learn. this post may contain estimates, may contain errors, and is provided on a best-effort basis. DYOR, make your own decisions.\n11. if you think im doing it wrong, REeEEeeeE at my in the comments.\n12. if you think im doing it wrong, and constructively/earnestly want to help right the ship, @ me on http://gov.gitcoin.co - make sure you tag the transition stewards (there are a half dozen of them, and they're here to hold all of us accountable to a new direction!)\n\ntldr\n1. what we care about is people using this stuff where they live. the 1st private alpha is live but that number is small today.\n2. if you want to help, the most useful thing you can do is fill out this form and start contributing: https://forms.gle/gh7vNtZJhpCBBRJD9\n3. lets not get ahead of ourselves.  \n4. yall shouldve heeded the words of @VitalikButerin in 2017 and you should heed mine today - ask yourself \"have we earned it?\"", "name": "owockai", "handle": "owocki", "avatar": "https://pbs.twimg.com/profile_images/2077424653321330688/bavMzvyd_200x200.jpg", "likes": 92, "rts": 14, "replies": 22, "views": 7633, "ts": 1792445549, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVBcHfQa0AAXM2G.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112655582671093801", "url": "https://x.com/AnupamPKher/status/2112655582671093801", "text": "एक-दो दिन पहले एक वीडियो देखा, जिसमें कोई मंत्री जी मंच पर दलेर मेहंदी जी से जिस तरह बात कर रहे थे, उसे देखकर बहुत दुख हुआ।\nमैं दलेर जी को बहुत सालों से जानता हूँ। यह भी जानता हूँ कि पिछले कुछ समय से उनकी तबीयत ठीक नहीं रही है। मंत्री जी, आपको उनकी प्रस्तुति से शिकायत हो सकती है। नाराज़गी भी हो सकती है। लेकिन सबके सामने मंच पर जाकर इस तरह उन्हें अपमानित करना ज़रूरी था क्या? यही बात उनसे अलग बैठकर, इज़्ज़त से भी तो कही जा सकती थी।\nएक कलाकार अपनी मेहनत से जो पहचान और सम्मान कमाता है, उसके पीछे पूरी ज़िंदगी लगी होती है। दलेर जी ने पिछले तीस-पैंतीस सालों से अपने गानों से हम सबको ख़ुशी दी है। उस योगदान की कुछ तो क़द्र होनी चाहिए।\nदलेर जी, मैंने आपको हमेशा एक नेकदिल, प्यार बाँटने वाले इंसान के रूप में जाना है। जहाँ तक मैं आपको जानता हूँ, आप शराब भी नहीं पीते। आपको यह सब सहना पड़ा, इसका मुझे बहुत अफ़सोस है।\nअपनी इंडस्ट्री के साथियों से भी कहना चाहूँगा—जो लोग दलेर जी को जानते हैं, वे अपनी बात ज़रूर रखें। उनके साथ खड़े हों। किसी के अच्छे स्वभाव के बारे में, उसकी इंसानियत के बारे में अपने अनुभव से दो शब्द कहना भी बहुत मायने रखता है। ऐसे वक़्त में एक साथी के लिए इतना तो हम कर ही सकते हैं।\nदलेर जी, आप बेहतरीन कलाकार हैं और उतने ही प्यारे इंसान भी। अपना ख़याल रखिए। भगवान आपको अच्छी सेहत दे। मेरा प्यार और सम्मान हमेशा आपके साथ है। 🙏❤️", "name": "Anupam Kher", "handle": "AnupamPKher", "avatar": "https://pbs.twimg.com/profile_images/1974464208218513408/ugtpO77S_200x200.jpg", "likes": 6037, "rts": 618, "replies": 511, "views": 501350, "ts": 1792531316, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112655395940397056/vid/avc1/720x1280/Kdo_A-2JzYLE51f_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112655395940397056/vid/avc1/1080x1920/viz4jfwqNtucnOXv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112655395940397056/img/IZYwC3iM3qed9eSD.jpg", "dur": 179}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVGo46qWQAECioF.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112583299352895988", "url": "https://x.com/ajaymehta/status/2112583299352895988", "text": "So much fun joining @philgcarter on his pod to talk about what makes Tolan unique.\n\nAnd of course, everyone's favorite topic: app monetization. The playbook's being rewritten in an era where usage comes with marginal cost - proud of how our team has led the charge 📈", "name": "Ajay Mehta", "handle": "ajaymehta", "avatar": "https://pbs.twimg.com/profile_images/793302000653991936/UixLX4vu_200x200.jpg", "likes": 51, "rts": 4, "replies": 3, "views": 3648, "ts": 1792514083, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112581475279499264/vid/avc1/640x360/8X8MUio5hGgq2Fbr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112581475279499264/vid/avc1/1280x720/V0FgdnO-pIIW_csV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112581475279499264/img/Ae2JN9iHQSPkpY8P.jpg", "dur": 40}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112633155631108544", "url": "https://x.com/ThePHPF/status/2112633155631108544", "text": "The PHP security team is giving advance notice: Upcoming security release Wed, Oct 21st 2026, 14:00UTC, two critical vulnerabilities, both rated CVSSv4 9.2.\n\nPHP users are encouraged to prepare to update. Earlier release if details become public or active exploit evidence.", "name": "The PHP Foundation", "handle": "ThePHPF", "avatar": "https://pbs.twimg.com/profile_images/1462756177696206854/YcHaTzic_200x200.jpg", "likes": 5491, "rts": 1325, "replies": 94, "views": 994570, "ts": 1792525969, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.28, "thread": [], "tier": "worth"}, {"id": "2112687409544733161", "url": "https://x.com/parth_29/status/2112687409544733161", "text": "Building models that deeply understand and collaborate with us has never been more important. This requires a dedicated effort and significant investment.\nAmpersand & is our first attempt to build such a model and is built by a team that deeply believes in the mission. @saurabh_shah2 @joeyxhong @YuchenHe07 haven’t seen ☀️ for a month now? 🐐 \nWe built the training stack for really long-horizon simulations powered by Persimmon and there is soo much more to do from systems, simulations, evals, algorithms and products!", "name": "Parth Chadha", "handle": "parth_29", "avatar": "https://pbs.twimg.com/profile_images/1718663914286977024/9tIfBUII_200x200.jpg", "likes": 23, "rts": 5, "replies": 6, "views": 2198, "ts": 1792538904, "media": [], "quote": {"id": "2112674550907552137", "url": "https://x.com/humansand/status/2112674550907552137", "text": "No one changes the world alone\nIntroducing Ampersand - the first model built for us. Ampersand is a collaborator trained to help people achieve their individual and collective goals. In multi-month simulations, users collaborating with Ampersand accomplished more than with Fable and other frontier models\nAvailable to everyone through our API", "name": "humans&", "handle": "humansand", "avatar": "https://pbs.twimg.com/profile_images/2013582555933478912/JKuMlTII_200x200.jpg", "likes": 801, "rts": 96, "replies": 70, "views": 115146, "ts": 1792535839, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1280x720/diVwgP2fN9mNUINm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1920x1080/BeqyLOSxKBxRevC6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664844772278272/img/eMd4u-rAwyUJpqWU.jpg", "dur": 32}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.28, "thread": [], "tier": "worth"}]);